import numpy as np
from .base import BaseLayer


def _pool_slices(x, kernel_size, stride):
    n, h, w, c = x.shape
    k, s = kernel_size, stride
    oh = (h - k) // s + 1
    ow = (w - k) // s + 1
    for i in range(k):
        for j in range(k):
            yield x[:, i:i + s * (oh - 1) + 1:s, j:j + s * (ow - 1) + 1:s, :]


class MaxPool2D(BaseLayer):
    def __init__(self, kernel_size, stride=None):
        super().__init__()
        self.kernel_size = int(kernel_size)
        self.stride = int(stride) if stride is not None else self.kernel_size

    def forward(self, x):
        x = np.asarray(x, dtype=np.float64)
        out = None
        for patch in _pool_slices(x, self.kernel_size, self.stride):
            out = patch.copy() if out is None else np.maximum(out, patch)
        return out.astype(np.float64)


class AvgPool2D(BaseLayer):
    def __init__(self, kernel_size, stride=None):
        super().__init__()
        self.kernel_size = int(kernel_size)
        self.stride = int(stride) if stride is not None else self.kernel_size

    def forward(self, x):
        x = np.asarray(x, dtype=np.float64)
        out = None
        for patch in _pool_slices(x, self.kernel_size, self.stride):
            out = patch.copy() if out is None else out + patch
        return (out / (self.kernel_size * self.kernel_size)).astype(np.float64)
